  port: number,
  timeoutMs = 60000,
  label: string = String(port),
  host = '127.0.0.1',
  portCheckFn: (p: number, h?: string) => Promise<boolean> = isPortOpen
): Promise<boolean> {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (await portCheckFn(port, host)) return true;
    await sleep(500);
  }
